import{_ as i,o as s,c as a,a2 as t}from"./chunks/framework.CHeM0PsO.js";const u=JSON.parse('{"title":"Public plugin webhooks","description":"","frontmatter":{"rfc":40,"title":"Public plugin webhooks","status":"Implemented","date":"June 2026","author":"kasunben","scope":"packages/manifest, runtime middleware, runtime route guard, packages/sdk, docs; builds on RFC 0042 and RFC 0043","incorporated_into_plan":"Yes — epic task 2.15","sourceUrl":"https://github.com/sovereignfs/sovereign/blob/main/docs/rfcs/0050-public-plugin-webhooks.md"},"headers":[],"relativePath":"rfcs/0050-public-plugin-webhooks.md","filePath":"rfcs/0050-public-plugin-webhooks.md"}'),o={name:"rfcs/0050-public-plugin-webhooks.md"};function n(r,e,l,d,h,c){return s(),a("div",null,[...e[0]||(e[0]=[t(`<h1 id="rfc-0050-—-public-plugin-webhooks" tabindex="-1">RFC 0050 — Public Plugin Webhooks <a class="header-anchor" href="#rfc-0050-—-public-plugin-webhooks" aria-label="Permalink to &quot;RFC 0050 — Public Plugin Webhooks&quot;">​</a></h1><h2 id="summary" tabindex="-1">Summary <a class="header-anchor" href="#summary" aria-label="Permalink to &quot;Summary&quot;">​</a></h2><p>Add a manifest-declared webhook ingress primitive for plugins that need to receive unauthenticated callbacks from external systems. Webhook routes are public at the middleware layer, but the plugin must verify signatures, reject replays, enforce body limits, and fail closed.</p><p>This is distinct from RFC 0042 public page routes. Public pages render content to humans. Webhooks accept machine-to-machine callbacks such as message delivery, payment events, provider sync notifications, or OAuth provider postbacks that are not browser callback flows.</p><h2 id="motivation" tabindex="-1">Motivation <a class="header-anchor" href="#motivation" aria-label="Permalink to &quot;Motivation&quot;">​</a></h2><p>Plugins that integrate with external providers often need inbound callbacks:</p><ul><li>email, chat, or social providers notifying that new messages are available;</li><li>payment providers reporting payment success/failure;</li><li>document-signing or form providers posting completed payloads;</li><li>provider-specific verification challenges.</li></ul><p>Today public API delegation is too coarse: it allows one plugin to own public <code>/api/*</code>, but it does not provide a per-plugin webhook declaration, consistent limits, or standard security expectations.</p><h2 id="current-state" tabindex="-1">Current state <a class="header-anchor" href="#current-state" aria-label="Permalink to &quot;Current state&quot;">​</a></h2><ul><li>Public <code>/api/*</code> delegation exists for one provider plugin.</li><li>RFC 0042 covers public page routes.</li><li>RFC 0043 covers secret storage for webhook signing secrets.</li><li>There is no narrow manifest declaration for public plugin webhook endpoints.</li></ul><h2 id="proposed-design" tabindex="-1">Proposed design <a class="header-anchor" href="#proposed-design" aria-label="Permalink to &quot;Proposed design&quot;">​</a></h2><p><strong>As shipped, this matches the sketch below closely</strong> — see the 0.2 changelog entry for the few real deviations (<code>sdk.webhooks.checkReplay()</code> returns &quot;is this new/safe&quot; rather than &quot;is this a replay,&quot; <code>requiresSignature</code> is documentation-only metadata with no enforcement of its own, and body-size limits have a documented gap for chunked-transfer bodies). See <code>docs/plugin-development.md</code>&#39;s &quot;webhooks&quot; section for the actual shipped surface and examples.</p><h3 id="manifest-declarations" tabindex="-1">Manifest declarations <a class="header-anchor" href="#manifest-declarations" aria-label="Permalink to &quot;Manifest declarations&quot;">​</a></h3><p>Add optional <code>webhooks</code> to plugin manifests:</p><div class="language-jsonc vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">jsonc</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;webhooks&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;path&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;/webhooks/provider&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;description&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Provider delivery callback&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;methods&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;POST&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">],</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;maxBodyBytes&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">262144</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;requiresSignature&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    },</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  ],</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>Rules:</p><ul><li><code>path</code> is relative to the plugin <code>routePrefix</code>.</li><li>paths must start with <code>/</code> and cannot be <code>/</code>;</li><li>methods are restricted to <code>POST</code> by default, with <code>GET</code> allowed only for provider verification challenges;</li><li>webhook routes never inherit public page route behavior;</li><li>disabled plugins return 404 for webhook routes.</li></ul><h3 id="runtime-behavior" tabindex="-1">Runtime behavior <a class="header-anchor" href="#runtime-behavior" aria-label="Permalink to &quot;Runtime behavior&quot;">​</a></h3><p>For declared webhook routes, middleware:</p><ol><li>skips the session redirect;</li><li>preserves CSP and security headers where applicable;</li><li>applies request body and method limits before invoking plugin code;</li><li>injects plugin ID and tenant context;</li><li>never injects a forged user identity.</li></ol><p>The plugin route handler verifies provider-specific authorization.</p><h3 id="sdk-helpers" tabindex="-1">SDK helpers <a class="header-anchor" href="#sdk-helpers" aria-label="Permalink to &quot;SDK helpers&quot;">​</a></h3><p>Add small server-side helpers rather than a full provider framework:</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">sdk.webhooks.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">verifyHmac</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(input: {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  body: Uint8Array;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  signatureHeader: string;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  secretRef: string;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  algorithm: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;sha256&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;sha512&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}): </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Promise</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">boolean</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">sdk.webhooks.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">checkReplay</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(input: {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  provider: string;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  eventId: string;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  timestamp</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">?:</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> number;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  ttlSeconds</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">?:</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> number;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}): </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Promise</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">boolean</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span></code></pre></div><p>Replay state is platform-owned so plugins do not need to reimplement a durable dedupe table for every provider.</p><h2 id="security-requirements" tabindex="-1">Security requirements <a class="header-anchor" href="#security-requirements" aria-label="Permalink to &quot;Security requirements&quot;">​</a></h2><ul><li>Undeclared webhook paths remain session-gated or unavailable.</li><li>Webhook route declarations are validated at build/install time.</li><li>Request body size limits apply before plugin handler execution.</li><li>Signature verification secrets are read through the secret vault.</li><li>Replay protection is available for providers with stable event IDs.</li><li>Invalid signatures return 404 or 401 without revealing whether a resource exists.</li><li>Webhook failures are sanitized and rate-limited to avoid log/DB flooding.</li></ul><h2 id="alternatives-considered" tabindex="-1">Alternatives considered <a class="header-anchor" href="#alternatives-considered" aria-label="Permalink to &quot;Alternatives considered&quot;">​</a></h2><h3 id="reuse-public-page-routes" tabindex="-1">Reuse public page routes <a class="header-anchor" href="#reuse-public-page-routes" aria-label="Permalink to &quot;Reuse public page routes&quot;">​</a></h3><p>Rejected. Webhooks need method/body limits, signature helpers, replay handling, and different audit semantics.</p><h3 id="keep-the-single-public-api-provider-model" tabindex="-1">Keep the single public API provider model <a class="header-anchor" href="#keep-the-single-public-api-provider-model" aria-label="Permalink to &quot;Keep the single public API provider model&quot;">​</a></h3><p>Rejected. It blocks multiple plugins from receiving provider callbacks.</p><h3 id="require-external-reverse-proxies-for-webhooks" tabindex="-1">Require external reverse proxies for webhooks <a class="header-anchor" href="#require-external-reverse-proxies-for-webhooks" aria-label="Permalink to &quot;Require external reverse proxies for webhooks&quot;">​</a></h3><p>Rejected. It makes plugin installation operator-hostile and weakens portability.</p><h2 id="open-questions" tabindex="-1">Open questions <a class="header-anchor" href="#open-questions" aria-label="Permalink to &quot;Open questions&quot;">​</a></h2><p><em>Resolved — see the 0.2 changelog entry for the full implementation:</em></p><ol><li><strong>Should webhook route paths live under <code>/api/&lt;pluginPrefix&gt;/...</code> regardless of plugin page route prefix?</strong> No — <code>webhooks[].path</code> resolves to <code>&lt;routePrefix&gt;&lt;path&gt;</code>, the same convention <code>publicRoutes</code> uses, and is unrelated to the <code>/api/*</code> public-namespace-delegation mechanism (PLT-16, <code>apiProvider</code>) entirely. A plugin&#39;s webhook <code>route.ts</code> is composed into the runtime route tree exactly like any other plugin route.</li><li><strong>Should the platform provide per-webhook rate limiting in v1?</strong> No. <code>runtime/middleware.ts</code>&#39;s existing general per-IP rate limiter still applies (webhook requests go through the same middleware pipeline), but there is no rate limit scoped to an individual declared webhook. Flagged as a real gap for a future task, not a silent omission — a provider retry storm on one webhook endpoint is only bounded by the instance-wide per-IP limit today.</li><li><strong>Should successful webhook events be visible in Console, or only failures?</strong> Neither, in this leg — there is no Console UI surface for webhook activity at all (success or failure). A plugin that wants visibility must log its own activity via <code>sdk.activity.log()</code>. Flagged as a follow-up, not built here.</li><li><strong>Should webhook verification challenge routes support unauthenticated <code>GET</code>?</strong> Yes — <code>methods: [&#39;GET&#39;]</code> is a supported per-declaration choice, exactly for this case; <code>POST</code> is the default when <code>methods</code> is omitted.</li></ol><h2 id="adoption-path" tabindex="-1">Adoption path <a class="header-anchor" href="#adoption-path" aria-label="Permalink to &quot;Adoption path&quot;">​</a></h2><ol><li>✅ Add manifest <code>webhooks</code> declarations and validation (<code>packages/manifest/src/schema.ts</code>).</li><li>✅ Extend middleware route decisions for declared webhook paths (<code>runtime/src/route-guard.ts</code>&#39;s <code>matchedWebhookRoute</code>, <code>runtime/middleware.ts</code>).</li><li>✅ Add request method/body limits (enforced in middleware before the plugin&#39;s route handler runs — see open question 2 for what this doesn&#39;t cover, and the 0.2 changelog for the <code>Content-Length</code> caveat).</li><li>✅ Add signature and replay SDK helpers (<code>sdk.webhooks.verifyHmac()</code>/ <code>checkReplay()</code>).</li><li>✅ Document provider webhook implementation patterns and tests (<code>docs/plugin-development.md</code>).</li></ol><h2 id="changelog" tabindex="-1">Changelog <a class="header-anchor" href="#changelog" aria-label="Permalink to &quot;Changelog&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Version</th><th>Date</th><th>Change</th></tr></thead><tbody><tr><td>0.1</td><td>June 2026</td><td>Initial draft</td></tr><tr><td>0.2</td><td>August 2026</td><td>Full manifest-declared webhooks shipped (epic task 2.15, workstream 0015 leg 3). Manifest <code>webhooks</code> field (<code>path</code>/<code>description</code>/<code>methods</code>/<code>maxBodyBytes</code>/<code>requiresSignature</code>) mirrors <code>publicRoutes</code>&#39; (RFC 0042) validation shape, but <code>path</code> is an <strong>exact</strong> match, not a prefix — <code>matchedWebhookRoute()</code> (<code>runtime/src/route-guard.ts</code>), resolving open question 1. <code>runtime/middleware.ts</code> adds a webhook bypass branch ahead of the public-page-route branch: disabled-plugin → 404, undeclared method → 404 (never 405 — never reveal accepted methods), <code>Content-Length</code> over <code>maxBodyBytes</code> → 413, plugin id injected, <strong>no</strong> <code>x-sovereign-user-*</code> header ever set (even with a valid session cookie — there is no user for a webhook call, unlike <code>publicRoutes</code> which does forward session headers when present). <code>sdk.webhooks.verifyHmac()</code>/<code>checkReplay()</code> (<code>packages/sdk/src/webhooks.ts</code>) take <code>requestHeaders</code> as a <strong>required</strong> argument and fail closed (<code>false</code>) rather than defaulting to <code>&#39;unknown&#39;</code> — no legitimate webhook call site lacks one. <code>verifyHmac()</code> accepts only <code>&#39;plugin&#39;</code>-scoped secrets (<code>runtime/src/sdk-host.ts</code>&#39;s <code>webhooks.verifyHmac</code>, secret lookup via <code>getPluginSecret</code>/<code>decryptSecretValue</code>) — <code>&#39;user&#39;</code>-scoped is inapplicable (no user) and <code>&#39;instance&#39;</code>-scoped is deliberately not exposed here since its normal capability check (<code>instance:configure</code>) needs a user context this call never has. The HMAC comparison itself (<code>runtime/src/webhook-hmac.ts</code>&#39;s <code>verifyHmacDigest</code>) computes a hex digest and does a length-checked <code>timingSafeEqual</code> against the caller-supplied <code>signatureHeader</code> — compared as a hex <strong>string</strong>, not decoded first (decoding malformed hex never throws in Node, so string comparison is simpler and no less safe); provider-specific prefixes (e.g. GitHub&#39;s <code>sha256=</code>) must be stripped by the caller first, this helper doesn&#39;t parse header formats. <code>checkReplay()</code> — the RFC&#39;s sketch didn&#39;t specify return-value polarity; resolved as <code>true</code> = &quot;new, safe to process,&quot; <code>false</code> = &quot;replay&quot; (a &quot;claim, not query&quot; semantics), backed by a new <code>webhook_replays</code> platform table (<code>packages/db</code>, unique index on <code>(pluginId, provider, eventId)</code>, atomic <code>INSERT ... ON CONFLICT DO NOTHING ... RETURNING</code> claim, 24h default TTL, expired rows deleted before each claim attempt so an old event id can be legitimately reprocessed rather than blocked forever) — the RFC sketch&#39;s <code>timestamp</code> input field was dropped since this design keys expiry off server receipt time, not a provider-supplied timestamp. Open questions 2 (per-webhook rate limiting) and 3 (Console visibility) remain unresolved — see their entries below for why neither blocks this leg.</td></tr></tbody></table>`,41)])])}const k=i(o,[["render",n]]);export{u as __pageData,k as default};
